mapper.insert:
insert into b_push_customer_detail
    (score_id, file_id, api_code,
    cust_num, user_type, cell,
    task_id, request_id, push_json,
    score_sort1, score_sort2, score_sort3,
    score_sort4,create_time)
values

        (#{dto.scoreId},#{dto.fileId},#{dto.apiCode}
        ,#{dto.custNum},#{dto.userType},#{dto.cell}
        ,#{dto.taskId},#{dto.requestId}


                ,#{dto.pushJson}


                ,null




                ,#{dto.scoreSort1}


                ,null




                ,#{dto.scoreSort2}


                ,null




            ,#{dto.scoreSort3}


            ,null




                ,#{dto.scoreSort4}


                ,null


        ,#{dto.createTime})

mapper.select:
select task_id
from (select task_id
      from b_push_customer_detail
      where file_id = #{fileId}
      group by task_id) as t
order by task_id limit #{pageIndex}, #{pageSize}
